<?php
declare(strict_types=1);session_start();require dirname(__DIR__).'/config/config.php';require_once __DIR__.'/lib/school_sms.php';require_sign_in();
$db=db();$uid=(int)$_SESSION['user_id'];$role=(string)$_SESSION['role'];$system=in_array($role,['system_admin','sub_admin'],true);$asyncRequest=str_contains((string)($_SERVER['HTTP_ACCEPT']??''),'application/json');function accounting_json(int $status,array $data):never{http_response_code($status);header('Content-Type: application/json; charset=utf-8');header('Cache-Control: no-store');echo json_encode($data,JSON_THROW_ON_ERROR|JSON_UNESCAPED_UNICODE);exit;}
if($system){header('Location: subscriptions.php#income');exit;}
$allowed=['admin','director','sub_director','headteacher','bursar'];$canReverse=in_array($role,['admin','director','sub_director','headteacher','bursar'],true);if(!in_array($role,$allowed,true)){http_response_code(403);exit('Your role cannot access school fee accounts.');}
$q=$db->prepare('SELECT s.id,s.name FROM schools s JOIN school_memberships m ON m.school_id=s.id WHERE m.user_id=? ORDER BY s.name');$q->execute([$uid]);$schools=$q->fetchAll();$schoolIds=array_map('intval',array_column($schools,'id'));if(!$schoolIds){http_response_code(403);exit('No school is linked to your account.');}$school=(int)($_GET['school_id']??$_POST['school_id']??$schoolIds[0]);if(!in_array($school,$schoolIds,true)){http_response_code(403);exit('That school is outside your access.');}$schoolName='School';foreach($schools as $s)if((int)$s['id']===$school)$schoolName=$s['name'];$error='';$notice='';$selectedPupil=(int)($_GET['pupil_id']??$_POST['pupil_id']??0);
if($_SERVER['REQUEST_METHOD']==='POST'){if($asyncRequest){if(!hash_equals($_SESSION['csrf']??'',(string)($_POST['csrf']??'')))accounting_json(400,['ok'=>false,'message'=>'Your session expired. Refresh the page and try again.']);}else verify_csrf();try{$action=(string)($_POST['action']??'record_entry');if($action==='queue_fee_reminder'){if(!$asyncRequest)throw new DomainException('Fee reminders must be requested asynchronously.');$pupil=(int)($_POST['pupil_id']??0);$db->beginTransaction();$q=$db->prepare("SELECT id FROM pupils WHERE id=? AND school_id=? AND status='active' FOR UPDATE");$q->execute([$pupil,$school]);if(!$q->fetchColumn())throw new DomainException('Choose an active pupil in this school.');$q=$db->prepare("SELECT COALESCE(SUM(CASE WHEN entry_type IN ('charge','payment_reversal','discount_reversal') THEN amount WHEN entry_type IN ('payment','charge_reversal','discount') THEN -amount ELSE 0 END),0) FROM school_fee_ledger WHERE school_id=? AND pupil_id=?");$q->execute([$school,$pupil]);$balance=(float)$q->fetchColumn();if($balance<=0)throw new DomainException('This pupil has no outstanding balance.');$q=$db->prepare('SELECT id FROM school_fee_ledger WHERE school_id=? AND pupil_id=? ORDER BY created_at DESC,id DESC LIMIT 1 FOR UPDATE');$q->execute([$school,$pupil]);$source=(int)$q->fetchColumn();if(!$source)throw new DomainException('No fee ledger entry is available for this account.');$queued=queue_school_sms_event($db,$school,$pupil,'school_fee_ledger',$source,'fee_reminder',$uid);$q=$db->prepare('INSERT INTO audit_logs(actor_id,action,entity_type,entity_id,details) VALUES(?,?,?,?,?)');$q->execute([$uid,'queue_fee_reminder','school_fee_ledger',$source,json_encode(['school_id'=>$school,'pupil_id'=>$pupil,'recipients_queued'=>$queued],JSON_THROW_ON_ERROR)]);$db->commit();accounting_json(200,['ok'=>true,'message'=>$queued?'Generic fee reminder queued for opted-in linked guardians.':'No opted-in guardian with a usable phone was available, or this reminder was already queued.','data'=>['queued'=>$queued,'balance'=>$balance]]);}$type=(string)($_POST['entry_type']??'');$pupil=(int)($_POST['pupil_id']??0);$year=filter_var($_POST['academic_year']??null,FILTER_VALIDATE_INT);$term=trim((string)($_POST['term']??''));$description=trim((string)($_POST['description']??''));$amount=filter_var($_POST['amount']??null,FILTER_VALIDATE_FLOAT);$method=trim((string)($_POST['payment_method']??''));$reference=trim((string)($_POST['reference']??''));if(!in_array($type,['charge','payment'],true)||!$pupil||$year===false||$year<2000||$year>2100||!$term||mb_strlen($term)>40||!$description||mb_strlen($description)>180||$amount===false||$amount<=0||$amount>100000000||mb_strlen($method)>40||mb_strlen($reference)>100)throw new DomainException('Enter a pupil, year, term, description and valid amount.');$q=$db->prepare("SELECT id FROM pupils WHERE id=? AND school_id=? AND status='active' FOR UPDATE");$db->beginTransaction();$q->execute([$pupil,$school]);if(!$q->fetchColumn())throw new DomainException('Choose an active pupil in this school.');if($type==='payment'){$q=$db->prepare("SELECT COALESCE(SUM(CASE WHEN entry_type IN ('charge','payment_reversal','discount_reversal') THEN amount WHEN entry_type IN ('payment','charge_reversal','discount') THEN -amount ELSE 0 END),0) FROM school_fee_ledger WHERE school_id=? AND pupil_id=? AND academic_year=? AND term=?");$q->execute([$school,$pupil,$year,$term]);$balance=(float)$q->fetchColumn();if($amount>$balance)throw new DomainException('Payment exceeds the outstanding balance for this pupil, year and term. Current balance: '.number_format($balance,2).'.');if(!$method)throw new DomainException('Choose a payment method for each receipt.');}$q=$db->prepare('INSERT INTO school_fee_ledger(school_id,pupil_id,entry_type,academic_year,term,description,amount,payment_method,reference,recorded_by) VALUES(?,?,?,?,?,?,?,?,?,?)');$q->execute([$school,$pupil,$type,$year,$term,$description,$amount,$type==='payment'?$method:null,$reference?:null,$uid]);$entry=(int)$db->lastInsertId();if($type==='payment')queue_school_sms_event($db,$school,$pupil,'school_fee_ledger',$entry,'fee_payment',$uid);$q=$db->prepare('INSERT INTO audit_logs(actor_id,action,entity_type,entity_id,details) VALUES(?,?,?,?,?)');$q->execute([$uid,$type==='payment'?'record_payment':'record_charge','school_fee_ledger',$entry,json_encode(['school_id'=>$school,'pupil_id'=>$pupil,'academic_year'=>$year,'term'=>$term,'amount'=>$amount,'payment_method'=>$type==='payment'?$method:null,'reference'=>$reference],JSON_THROW_ON_ERROR)]);$db->commit();if($asyncRequest){$q=$db->prepare('SELECT l.*,u.name recorder,0 is_reversed FROM school_fee_ledger l JOIN users u ON u.id=l.recorded_by WHERE l.id=?');$q->execute([$entry]);$savedEntry=$q->fetch();$q=$db->prepare("SELECT COALESCE(SUM(CASE WHEN entry_type IN ('charge','discount_reversal') THEN amount WHEN entry_type IN ('charge_reversal','discount') THEN -amount ELSE 0 END),0) charges,COALESCE(SUM(CASE WHEN entry_type='payment' THEN amount WHEN entry_type='payment_reversal' THEN -amount ELSE 0 END),0) payments FROM school_fee_ledger WHERE school_id=?");$q->execute([$school]);$savedTotals=$q->fetch();$q=$db->prepare("SELECT COALESCE(SUM(CASE WHEN entry_type IN ('charge','payment_reversal','discount_reversal') THEN amount WHEN entry_type IN ('payment','charge_reversal','discount') THEN -amount ELSE 0 END),0) FROM school_fee_ledger WHERE school_id=? AND pupil_id=?");$q->execute([$school,$pupil]);accounting_json(200,['ok'=>true,'message'=>$type==='payment'?'Payment receipt recorded.':'Fee charge added to the pupil account.','data'=>['entry'=>$savedEntry,'balance'=>(float)$q->fetchColumn(),'charges'=>(float)$savedTotals['charges'],'payments'=>(float)$savedTotals['payments'],'outstanding'=>(float)$savedTotals['charges']-(float)$savedTotals['payments']]]);}$notice=$type==='payment'?'Payment receipt recorded.':'Fee charge added to the pupil account.';$selectedPupil=$pupil;}catch(DomainException $e){if($db->inTransaction())$db->rollBack();$error=$e->getMessage();}catch(Throwable $e){if($db->inTransaction())$db->rollBack();$error='The fee entry could not be saved. Apply the latest database migration and check access.';if($asyncRequest)accounting_json(500,['ok'=>false,'message'=>$error]);}if($asyncRequest)accounting_json(422,['ok'=>false,'message'=>$error]);}
$q=$db->prepare("SELECT id,admission_number,first_name,middle_name,last_name,class_level FROM pupils WHERE school_id=? AND status='active' ORDER BY class_level,last_name,first_name");$q->execute([$school]);$pupils=$q->fetchAll();$q=$db->prepare("SELECT COALESCE(SUM(CASE WHEN entry_type IN ('charge','discount_reversal') THEN amount WHEN entry_type IN ('charge_reversal','discount') THEN -amount ELSE 0 END),0) charges,COALESCE(SUM(CASE WHEN entry_type='payment' THEN amount WHEN entry_type='payment_reversal' THEN -amount ELSE 0 END),0) payments FROM school_fee_ledger WHERE school_id=?");$q->execute([$school]);$totals=$q->fetch();$q=$db->prepare("SELECT p.id,p.admission_number,p.first_name,p.middle_name,p.last_name,p.class_level,p.status,b.balance FROM pupils p JOIN (SELECT pupil_id,SUM(CASE WHEN entry_type IN ('charge','payment_reversal','discount_reversal') THEN amount WHEN entry_type IN ('payment','charge_reversal','discount') THEN -amount ELSE 0 END) balance FROM school_fee_ledger WHERE school_id=? GROUP BY pupil_id HAVING balance>0) b ON b.pupil_id=p.id WHERE p.school_id=? ORDER BY b.balance DESC,p.class_level,p.last_name,p.first_name");$q->execute([$school,$school]);$arrears=$q->fetchAll();$arrearsTotal=array_sum(array_map(fn($r)=>(float)$r['balance'],$arrears));$rows=[];$balance=0;if($selectedPupil){$q=$db->prepare("SELECT COALESCE(SUM(CASE WHEN entry_type IN ('charge','payment_reversal','discount_reversal') THEN amount WHEN entry_type IN ('payment','charge_reversal','discount') THEN -amount ELSE 0 END),0) FROM school_fee_ledger WHERE school_id=? AND pupil_id=?");$q->execute([$school,$selectedPupil]);$balance=(float)$q->fetchColumn();$q=$db->prepare("SELECT l.*,u.name recorder,p.admission_number,p.first_name,p.middle_name,p.last_name,EXISTS(SELECT 1 FROM school_fee_ledger r WHERE r.reversal_of=l.id) is_reversed FROM school_fee_ledger l JOIN users u ON u.id=l.recorded_by JOIN pupils p ON p.id=l.pupil_id WHERE l.school_id=? AND l.pupil_id=? ORDER BY l.created_at DESC,l.id DESC LIMIT 250");$q->execute([$school,$selectedPupil]);$rows=$q->fetchAll();}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>School fees · ShuleLite</title><link rel="stylesheet" href="assets/app.css"><script defer src="assets/app.js"></script><script defer src="assets/api.js"></script><script defer src="assets/fees.js"></script></head><body><div class="app-shell"><?php require __DIR__.'/sidebar.php';?><main class="main-area"><header class="topbar"><button class="icon-button menu-toggle" data-menu aria-label="Open navigation" aria-expanded="false">☰</button><div class="crumb">Workspace <span>/</span> School fees</div><div class="top-actions"><span class="role-chip"><?=e(str_replace('_',' ',$role))?></span><div class="user-name"><?=e((string)($_SESSION['name']??'User'))?></div></div></header><div class="page-content" data-can-reverse="<?=$canReverse?'1':'0'?>"><section class="welcome-row"><div><div class="eyebrow">SCHOOL FINANCE</div><h1>Fee accounts</h1><p class="muted"><?=e($schoolName)?> · Record charges and payments against pupil balances.</p></div><?php if(count($schools)>1):?><form method="get"><label for="fee-school">School</label><select id="fee-school" name="school_id" onchange="this.form.submit()"><?php foreach($schools as $s):?><option value="<?=$s['id']?>"<?=(int)$s['id']===$school?' selected':''?>><?=e($s['name'])?></option><?php endforeach;?></select></form><?php endif;?><a class="button" href="fee_structures.php?school_id=<?=$school?>">Manage fee structures</a><a class="button" href="fee_reconciliation.php?school_id=<?=$school?>">Reconcile payments</a></section><?php if($error):?><div class="notice error" role="alert"><?=e($error)?></div><?php endif;?><?php if($notice):?><div class="notice success" role="status"><?=e($notice)?></div><?php endif;?>
<section class="metric-grid"><article class="metric-card"><div class="metric-label">FEE CHARGES</div><div class="metric-value" data-fee-charges><?=number_format((float)$totals['charges'],2)?></div><div class="metric-note">Net of reversals · KES</div></article><article class="metric-card"><div class="metric-label">PAYMENTS RECEIVED</div><div class="metric-value" data-fee-payments><?=number_format((float)$totals['payments'],2)?></div><div class="metric-note">Net receipts · KES</div></article><article class="metric-card"><div class="metric-label">OUTSTANDING</div><div class="metric-value" data-fee-outstanding><?=number_format((float)$totals['charges']-(float)$totals['payments'],2)?></div><div class="metric-note">Open pupil balances · KES</div></article></section>
<section class="content-section"><div class="section-heading"><div><div class="eyebrow">ARREARS</div><h2>Outstanding pupil balances</h2><p class="muted">Balances include recorded charges, payments and compensating reversals across all terms.</p></div><div><span class="count-pill"><?=count($arrears)?> pupils � KES <?=e(number_format($arrearsTotal,2))?></span> <a class="button" href="fee_arrears_export.php?school_id=<?=$school?>">Download CSV</a> <button class="button" type="button" onclick="window.print()">Print report</button></div></div><?php if($arrears):?><div class="table-wrap"><table><thead><tr><th>Pupil</th><th>Admission no.</th><th>Class</th><th>Status</th><th>Outstanding (KES)</th><th>Account</th></tr></thead><tbody><?php foreach($arrears as $debtor):?><tr><td><?=e(trim($debtor['first_name'].' '.$debtor['middle_name'].' '.$debtor['last_name']))?></td><td><?=e($debtor['admission_number'])?></td><td><?=e($debtor['class_level'])?></td><td><?=e(ucfirst($debtor['status']))?></td><td><?=e(number_format((float)$debtor['balance'],2))?></td><td><a class="button" href="accounting.php?school_id=<?=$school?>&amp;pupil_id=<?=$debtor['id']?>">Open account</a></td></tr><?php endforeach;?></tbody></table></div><?php else:?><div class="empty-state"><h3>No outstanding balances</h3><p>Active pupils currently have no net fee arrears.</p></div><?php endif;?></section>
<section class="content-section"><div class="section-heading"><div><div class="eyebrow">PUPIL ACCOUNTS</div><h2>Choose a pupil</h2></div><span class="count-pill"><?=count($pupils)?> active pupils</span></div><form method="get" class="ops-filter"><input type="hidden" name="school_id" value="<?=$school?>"><div><label for="fee-pupil">Pupil</label><select id="fee-pupil" name="pupil_id" required><option value="">Choose pupil</option><?php foreach($pupils as $p):?><option value="<?=$p['id']?>"<?=(int)$p['id']===$selectedPupil?' selected':''?>><?=e($p['admission_number'].' · '.trim($p['first_name'].' '.$p['middle_name'].' '.$p['last_name']).' · '.$p['class_level'])?></option><?php endforeach;?></select></div><button class="button" type="submit">Open account</button></form></section>
<?php if($selectedPupil):?><section class="note-create"><div class="section-heading"><div><div class="eyebrow">ACCOUNT ENTRY</div><h2>Record a fee charge or payment</h2><?php if($canReverse):?><button class="button" type="button" data-open-discount>Apply fee discount</button><?php endif;?><p class="muted">Current all-term balance: KES <span data-pupil-balance><?=number_format($balance,2)?></span></p><button class="button" type="button" data-queue-fee-reminder<?= $balance>0?"":" hidden" ?>>Queue fee reminder</button><p class="muted">Queued only for opted-in linked guardians. The generic message does not include a balance.</p></div></div><form method="post" class="note-form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="school_id" value="<?=$school?>"><input type="hidden" name="pupil_id" value="<?=$selectedPupil?>"><div class="form-grid"><div><label for="entry-type">Entry type</label><select id="entry-type" name="entry_type"><option value="charge">Add charge</option><option value="payment">Record payment</option></select></div><div><label for="fee-year">Academic year</label><input id="fee-year" name="academic_year" type="number" min="2000" max="2100" value="<?=date('Y')?>" required></div><div><label for="term">Term</label><input id="term" name="term" maxlength="40" placeholder="Term 1" required></div><div><label for="fee-description">Description</label><input id="fee-description" name="description" maxlength="180" placeholder="Tuition, meals or other fee" required></div><div><label for="amount">Amount (KES)</label><input id="amount" name="amount" type="number" step="0.01" min="0.01" required></div><div data-payment-field><label for="method">Payment method</label><select id="method" name="payment_method"><option value="">Choose method</option><?php foreach(['Cash','Bank transfer','Mobile money','Cheque','Other'] as $m):?><option><?=e($m)?></option><?php endforeach;?></select></div><div><label for="reference">Receipt or reference</label><input id="reference" name="reference" maxlength="100"></div></div><button class="button primary" type="submit">Save fee entry</button></form></section><section class="content-section"><div class="section-heading"><div><div class="eyebrow">ACCOUNT HISTORY</div><h2>Ledger entries</h2><a class="button" href="fee_statement.php?school_id=<?=$school?>&amp;pupil_id=<?=$selectedPupil?>">Print statement</a></div><span class="count-pill">KES <span data-pupil-balance><?=number_format($balance,2)?></span> outstanding</span></div><?php if($rows):?><div class="table-wrap"><table><thead><tr><th>Date</th><th>Year / term</th><th>Entry</th><th>Description</th><th>Amount</th><th>Method / reference</th><th>Recorded by</th><th>Action</th></tr></thead><tbody><?php foreach($rows as $r):?><tr data-ledger-row data-entry-id="<?=$r['id']?>" data-entry-type="<?=e($r['entry_type'])?>" data-reversal-of="<?=e((string)($r['reversal_of']??''))?>" data-reversed="<?=!empty($r['is_reversed'])?'1':'0'?>"><td><?=e(date('j M Y H:i',strtotime($r['created_at'])))?></td><td><?=e($r['academic_year'].' · '.$r['term'])?></td><td><?=e(match($r['entry_type']){'charge'=>'Charge','payment'=>'Payment','charge_reversal'=>'Charge reversal','payment_reversal'=>'Payment reversal','discount'=>'Fee discount','discount_reversal'=>'Discount reversal'})?></td><td><?=e($r['description'].(!empty($r['reversal_reason'])?' · Reason: '.$r['reversal_reason']:''))?></td><td><?=e((in_array($r['entry_type'],['charge','payment_reversal','discount_reversal'],true)?'+':'−').' '.number_format((float)$r['amount'],2))?></td><td><?=e(trim(($r['payment_method']??'').' '.($r['reference']??''))?:'—')?></td><td><?=e($r['recorder'])?></td><td data-ledger-action><?php if($r['entry_type']==='payment'):?><a class="button" href="fee_receipt.php?school_id=<?=$school?>&amp;entry_id=<?=$r['id']?>">Receipt</a> <?php endif;?><?php if($canReverse&&in_array($r['entry_type'],['charge','payment','discount'],true)&&empty($r['is_reversed'])):?><button type="button" class="button" data-open-reversal data-id="<?=$r['id']?>" data-label="<?=e(ucfirst($r['entry_type']).' · '.number_format((float)$r['amount'],2))?>">Reverse</button><?php elseif(!empty($r['reversal_of'])):?>Reverses #<?=$r['reversal_of']?><?php elseif(!empty($r['is_reversed'])):?>Reversed<?php else:?>—<?php endif;?></td></tr><?php endforeach;?></tbody></table></div><?php else:?><div class="empty-state"><h3>No fee entries yet</h3><p>Add a fee charge or record a payment to start this pupil’s account ledger.</p></div><?php endif;?></section><?php endif;?>
<footer class="page-footer">ShuleLite <span>·</span> School fee accounts · Entries are append-only and audited.</footer></div></main></div><script>const type=document.querySelector('#entry-type'),field=document.querySelector('[data-payment-field]'),method=document.querySelector('#method');function paymentState(){const paying=type.value==='payment';field.hidden=!paying;method.required=paying}type?.addEventListener('change',paymentState);paymentState()</script><dialog id="fee-reversal-dialog" class="subject-dialog"><form method="dialog"><div class="subject-dialog-head"><div><div class="eyebrow">TRANSACTION CONTROL</div><h2>Reverse fee entry</h2><p class="muted" id="fee-reversal-label"></p></div><button type="button" class="icon-button" data-close-fee-reversal aria-label="Close">×</button></div><div class="subject-dialog-body"><input type="hidden" id="fee-reversal-id"><label for="fee-reversal-reason">Reason <span class="muted">(required)</span></label><textarea id="fee-reversal-reason" maxlength="255" rows="4" required></textarea><p class="muted">A compensating entry will be added. The original charge or receipt will stay in the ledger.</p><div class="planning-actions"><button type="button" class="button danger" id="confirm-fee-reversal">Add reversal</button><button type="button" class="button" data-close-fee-reversal>Cancel</button></div></div></form></dialog><dialog id="fee-discount-dialog" class="subject-dialog"><form method="dialog"><div class="subject-dialog-head"><div><div class="eyebrow">FEE ADJUSTMENT</div><h2>Apply a pupil discount</h2></div><button type="button" class="icon-button" data-close-discount aria-label="Close">×</button></div><div class="subject-dialog-body"><p class="muted">The discount is recorded as an auditable ledger credit and cannot exceed the selected term balance.</p><label for="fee-discount-amount">Amount (KES)</label><input id="fee-discount-amount" type="number" min="0.01" step="0.01" required><label for="fee-discount-reason">Reason</label><textarea id="fee-discount-reason" maxlength="255" rows="3" required></textarea><div class="planning-actions"><button type="button" class="button primary" id="confirm-fee-discount">Apply discount</button><button type="button" class="button" data-close-discount>Cancel</button></div></div></form></dialog></body></html>
